  function batchStatus(status){const ids=[...state().selected];if(!ids.length)return;confirm('批量'+status,`将 ${ids.length} 个服务项目设置为${esc(status)}。下架后停止新售，历史卡项仍可按规则核销。`,()=>{S.transaction('服务项目批量'+status,d=>{for(const id of ids){const r=S.get('services',id,d);must(!r.mergedInto,'已合并项目不能重新上架');r.status=status}return {id:ids.join('、')}});state().selected=[]})}
  function workflow(type,id,action){if(type==='counts'&&action==='approve'&&S.get('counts',id)?.splitReview)return countReview(id);confirm(action==='deny'?'驳回申请':'确认处理','处理后将保留操作记录，并按单据更新关联库存或台账。',()=>{if(type==='losses'&&action==='approve')return S.approveLoss(id);if(type==='counts'&&action==='approve')return S.approveCount(id);S.transaction(type+' / '+action,d=>{const r=S.get(type,id,d);must(r,'记录不存在');if(type==='counts'){must(r.status==='待审核','状态已改变');r.status='待盘点';r.book=S.get('batches',r.batch,d).quantity;delete r.actual;return r}if(type==='settlements'){must(r.status==='待确认','状态已改变');r.status='已确认';return r}if(type==='adverse'){must(r.status==='待跟进','已结案');r.status='已结案';return r}if(type==='recalls'){must(r.status==='待执行','已执行');const source=S.get('batches',r.batch,d);d.batches.filter(b=>b.sku===source.sku&&b.batch===source.batch).forEach(b=>b.quality='召回锁定');d.udi.filter(u=>u.sku===source.sku&&d.batches.some(b=>b.id===u.batch&&b.batch===source.batch)).forEach(u=>u.status='已召回');r.status='执行中';return r}if(type==='payments'&&action==='paid'){must(r.status==='待付款','已处理');r.status='已付款';return r}must(r.status==='待审批','单据已处理');if(action==='deny'){r.status='已驳回';return r}if(type==='purchases')r.status='待收货';else if(type==='prices')r.status='已生效';else if(type==='payments')r.status='待付款';else if(type==='purchaseReturns'){const b=S.get('batches',r.batch,d);must(S.available(b)>=r.quantity,'批次库存不足');S.movement(d,b,-r.quantity,'采购退货',r.id);r.status='已退货'}else if(type==='adjustments'){const c=S.get('consumptions',r.source,d);must(c?.status==='已消耗','原消耗单已失效');let a=[];if(r.quantity>0){a=S.allocate(d,r.sku,c.store,r.quantity);S.guardClinical(d,a,c);a.forEach(x=>S.movement(d,S.get('batches',x.batch,d),-x.quantity,'消耗调整',r.id))}else{must(false,'旧退回调整须驳回，改走实物盘点与专项复核');const k=S.get('skus',r.sku,d);must(k.openHours>0,'缺少开封有效期配置');let skip=-(d.adjustments||[]).filter(x=>x.id!==id&&x.source===c.id&&x.sku===r.sku&&x.status==='已调整'&&x.quantity<0).reduce((n,x)=>n+x.quantity,0),left=-r.quantity;const source=c.allocations.filter(x=>x.sku===r.sku);must(left+skip<=source.reduce((n,x)=>n+x.quantity,0),'退回余量超过原消耗量');for(const x of source){let q=x.quantity;if(skip){const n=Math.min(skip,q);skip-=n;q-=n}q=Math.min(q,left);if(q>0){const original=S.get('batches',x.batch,d),opened=Date.parse(c.confirmed.replace(' ','T')+'+08:00'),expires=new Date(opened+k.openHours*3600000).toISOString();must(Date.parse(expires)>Date.now(),'原治疗开瓶余量已到期，请登记损耗');const b={...copy(original),id:uid('OPEN'),reserved:0,quantity:0,openedAt:c.confirmed,openExpiry:expires,parent:original.id,source:r.id,caseNo:c.caseNo};d.batches.push(b);S.movement(d,b,q,'消耗余量退回',r.id);a.push({batch:b.id,sku:b.sku,quantity:-q,cost:b.cost});left=round(left-q)}if(!left)break}}r.allocations=a;r.cost=round(a.reduce((n,x)=>n+x.quantity*x.cost,0));r.status='已调整'}else r.status='已通过';return r})})}
  function receive(id){const po=S.get('purchases',id),defs=[S.req('quantity','验收数量','number'),S.req('deliveryNo','送货单号'),S.req('invoiceNo','发票号码'),S.req('deliveryQuantity','送货单数量','number'),S.req('invoiceAmount','发票金额（元）','number'),S.req('batch','生产批号'),S.req('produced','生产日期','date'),S.req('expiry','有效期','date'),S.ref('warehouse','收货库位','warehouses'),S.f('boxCode','外箱聚合码'),S.f('udi','批次 UDI 码'),S.f('unitCodes','单支追溯码（每行一码）','textarea'),S.req('files','随货资料 / 检验报告')],m={quantity:po.quantity,deliveryQuantity:po.quantity,invoiceAmount:po.amount,deliveryNo:'',invoiceNo:'',batch:'',produced:'',expiry:'',warehouse:'',udi:'',boxCode:'',unitCodes:'',files:''};open('到货验收 · '+id,kv({'订单商品':text(names('skus',po.sku)),'订单数量':text(po.quantity+' '+po.unit),'基本单位记账':text((po.conversion?.baseQuantity??S.convertUnits(po.sku,po.quantity,po.unit))+' '+S.get('skus',po.sku).unit),'收货门店':text(names('stores',po.store))})+form(defs,m),r=>{validate(defs,r);S.purchaseReceive(id,r);saved('已验收入库，库存与采购应付同步更新')},m,860,'确认验收入库')}
  function transfer(id,a){const t=S.get('transfers',id),b=S.get('batches',t.batch),k=S.get('skus',b.sku);if(a==='receive'||a==='reject'){const defs=a==='receive'?[S.ref('warehouse','接收库位','warehouses'),S.f('receiveUnit','接收单位','select',S.unitsFor(k.id),true),S.req('receiveQuantity','实收数量','number')]:[S.req('reason','拒收原因','textarea')],m=a==='receive'?{warehouse:'',receiveUnit:k.stockUnit,receiveQuantity:round(t.quantity/S.unitFactor(k.id,k.stockUnit))}:{reason:''};open(a==='receive'?'确认调拨收货':'拒收并退回',kv({'发出数量':text(unitCell(t,'sendDisplay','transfers')),'应收基本量':text(t.quantity+' '+k.unit)})+form(defs,m),r=>{validate(defs,r);S.transferAction(id,a,r);saved()},m,560);return}confirm('确认调拨操作',a==='ship'?'发货后扣减调出店库存并转入在途，收货前不增加接收店库存。':a==='return'?'退回签收后恢复原调出店库存。':'确认处理当前调拨单。',()=>S.transferAction(id,a))}
  function countResult(id){const c=S.get('counts',id),b=S.get('batches',c.batch),k=S.get('skus',b.sku),defs=[S.f('stockUnit','盘点库存单位','select',S.unitsFor(k.id),true),S.req('whole','整件 / 整支数','number'),S.req('remainder','零量（'+k.unit+'）','number'),S.f('note','差异说明','textarea')],m={stockUnit:k.stockUnit,whole:0,remainder:0,note:''};open('登记双单位盘点',kv({'账面库存':text(stockDisplay(b.quantity,k.stockUnit,S.unitFactor(k.id,k.stockUnit),k.unit)),'瓶 / 批次':text(b.containerCode||b.batch),'库存归属':text(b.customerId?'客户寄存 / '+b.customerId:'门店库存')})+form(defs,m),r=>{validate(defs,r);S.registerCount(id,r);saved('盘点已提交；拆零差异须专项复核')},m,560,'提交审核')}
  function purchaseFrom(id){const a=S.get('applications',id);edit('purchases','',{sku:a.sku,store:a.store,quantity:a.quantity,unit:S.get('skus',a.sku).unit,price:S.get('skus',a.sku).cost,note:'来源采购申请：'+id})}
  function serviceSpecs(id){open('项目规格 · '+names('services',id),()=>tableFor('specs',S.data.specs.filter(s=>s.service===id))+button('新增规格','edit',['specs','',{service:id}],'primary'),null,null,860)}
  function lineTable(lines,kind){if(kind==='card')return table(['可核销服务规格','次数','操作'],lines.map((l,i)=>[select([['','请选择服务规格'],...optionList({key:'spec',options:'specs'})],l.spec,`name="line-${i}-spec" aria-label="卡内第${i+1}项服务" data-filterable="true"`),`<input type="number" name="line-${i}-times" aria-label="卡内第${i+1}项次数" value="${esc(l.times)}" min="1" step="1">`,link('移除','removeLine',i)]));return lines.map((l,i)=>{const k=S.get(l.type==='sku'?'skus':'equipment',l.item),defs=[S.f('type','类型','select',['sku','equipment'],true),S.ref('item','物料 / 仪器',l.type==='equipment'?'equipment':'skus'),S.f('unit','消耗单位','select',l.type==='equipment'?[k?.unit||'发']:S.unitsFor(l.item),true),S.req('quantity','标准用量','number'),S.req('min','最低用量','number'),S.req('max','最高用量','number'),...(l.type==='sku'?[S.f('alternatives','可选替代料','multi','skus')]:[])];let html=form(defs.map(f=>({...f,key:'line-'+i+'-'+f.key})),Object.fromEntries(Object.entries(l).map(([key,v])=>['line-'+i+'-'+key,v])),'sc-bom');html=html.replace('name="line-'+i+'-type"','onchange="'+esc(call('lineChange',i,'type'))+'" name="line-'+i+'-type"').replace('name="line-'+i+'-item"','onchange="'+esc(call('lineChange',i,'item'))+'" name="line-'+i+'-item"');return contentModule('配方第 '+(i+1)+' 项',html,link('移除','removeLine',i))}).join('')}
  function readLines(el,m){const lines=m.lines||m.contents;lines.forEach((l,i)=>{for(const k of Object.keys(l)){const c=el.querySelector(`[name="line-${i}-${k}"]`);if(c)l[k]=c.multiple?[...c.selectedOptions].map(o=>o.value):c.type==='number'?(c.value===''?'':Number(c.value)):c.value}if(l.type==='equipment')l.alternatives=[]})}
  function addLine(){collect();const m=top().model;if(m.lines)m.lines.push({type:'sku',item:'',quantity:1,unit:'',min:1,max:1,alternatives:[]});else m.contents.push({spec:'',times:1});redraw()}
  function removeLine(i){collect();const m=top().model;(m.lines||m.contents).splice(i,1);redraw()}
  function lineChange(i,key){collect();const l=top().model.lines?.[i];if(l){if(key==='type'){l.item='';l.alternatives=[]}if(key==='item'){const k=S.get(l.type==='sku'?'skus':'equipment',l.item);l.unit=(l.type==='sku'?k?.consumptionUnit:k?.unit)||k?.unit||'';l.alternatives=[]}}redraw()}
  function validateLines(m){S.normalizeBom(m);must(m.lines.length>0,'请至少配置一项物料或仪器');const seen=new Set();for(const l of m.lines){positive(l.quantity,'配方用量');must(S.get(l.type==='sku'?'skus':'equipment',l.item),'请选择有效的物料或仪器');must(!seen.has(l.type+l.item),'同一配方不能重复添加同一物料或仪器');seen.add(l.type+l.item);if(l.type==='sku'){const k=S.get('skus',l.item);must(l.alternatives.every(id=>id!==k.id&&S.get('skus',id)?.unit===k.unit),'替代料须与主物料使用相同基本单位')}}}
  function bom(id){const old=S.get('boms',id),m={id:'',name:old?.name||'',spec:old?.spec||'',effective:old?S.day(1):S.today(),lines:copy(old?.lines||[{type:'sku',item:'',quantity:1,unit:'',min:1,max:1,alternatives:[]}])},defs=[S.req('name','配方名称'),S.ref('spec','服务规格','specs'),S.req('effective','生效日期','date')];open(old?'创建 BOM 新版本':'新建 BOM 配方',r=>form(defs,r)+contentModule('物料与仪器配方',lineTable(r.lines,'bom'),button('添加用料','addLine'))+'<p class="muted">每项用料须填写单位、标准用量和浮动区间。发布时保存换算快照，超范围实际用量进入审批。</p>',r=>{validate(defs,r);validateLines(r);S.publishBom(r);saved('BOM 版本已发布')},m,1120,'发布版本');top().read=readLines}
  function validateContents(r){must(r.contents.length,'请至少添加一个可核销项目');const seen=new Set();for(const c of r.contents){must(S.get('specs',c.spec),'请选择有效规格');must(S.get('services',S.get('specs',c.spec).service)?.card,'所选项目不允许组卡');must(Number.isInteger(c.times)&&c.times>0,'次数须为正整数');must(!seen.has(c.spec),'同一规格不能重复配置');seen.add(c.spec)}}
  function cardContent(id){const parent=!id?top():null,card=id?S.get('cards',id):parent?.model;if(!card)return;const m={contents:copy(card.contents||[])};open('配置卡内权益',r=>contentModule('可核销服务项目',lineTable(r.contents,'card'),button('添加项目','addLine')),r=>{validateContents(r);if(parent){parent.model.contents=copy(r.contents);close(true);redraw()}else{S.save('cards',{...copy(card),contents:r.contents});saved()}},m,860);top().read=readLines}
  function mergeUI(){const defs=[S.ref('target','合并目标项目','services'),S.f('sources','待合并项目','multi',[]),S.req('reason','合并原因','textarea')],m={target:'',sources:[],reason:''};defs[1].options='services';open('项目合并',r=>form(defs,r)+'<p class="muted">来源项目下架，规格归入目标项目。历史订单快照保留，存量卡权益与 BOM 继续使用原规格编号。</p>',r=>{validate(defs,r);S.merge(r);saved('项目合并完成')},m,860,'确认合并')}
  function recharge(id){const defs=[S.ref('equipment','仪器账户','equipment'),S.req('quantity','充值发数','number'),S.req('amount','采购金额（元）','number'),S.req('voucher','采购凭证号')],m={equipment:id||'',quantity:'',amount:'',voucher:''};open('发数账户充值',form(defs,m),r=>{validate(defs,r);positive(r.quantity,'充值发数');must(Number.isInteger(r.quantity)&&r.amount>=0,'发数须为正整数，金额不能为负');S.transaction('发数采购充值',d=>{const e=S.get('equipment',r.equipment,d);e.shots+=r.quantity;e.totalShots+=r.quantity;const log={...r,id:uid('SHOT'),kind:'采购充值',time:S.stamp(),status:'已入账'};d.shotLogs.unshift(log);return log});saved()},m,560)}
  function sellCardUI(){const defs=[S.ref('card','卡项','cards'),S.req('customer','客户 / 会员号'),S.ref('store','售卡门店','stores')],m={card:'',customer:'',store:''};open('售卡登记',form(defs,m)+'<p class="muted">售卡记录预收金额，核销后结转收入并按 BOM 扣减物料。</p>',r=>{validate(defs,r);S.sellCard(r);saved('已生成预收及卡内权益')},m,560)}
  function consumeUI(redeem=false){const defs=[...(redeem?[S.ref('cardSale','客户卡项','cardSales')]:[S.req('customer','客户 / 会员号')]),S.req('customerId','客户 ID'),S.ref('store','消耗门店','stores'),S.ref('spec','服务项目规格','specs'),S.req('times','服务次数','number'),S.ref('authorizer','授权店长','managers',false),S.ref('doctor','操作医生','doctors',false),S.f('caseNo','病例号'),S.f('consent','知情同意书编号'),S.ref('operator','登记人员','staff',false),S.ref('reviewer','复核人员','staff',false)],m={customer:'',customerId:'',cardSale:'',store:'',spec:'',times:1,authorizer:'',doctor:'',caseNo:'',consent:'',operator:'',reviewer:'',alternatives:{}};open(redeem?'卡项核销申请':'项目消耗申请',r=>{const bom=S.activeBom(r.spec),base=form(defs,r).replace('name="spec"','onchange="'+esc(call('consumeChange'))+'" name="spec"').replace('name="cardSale"','onchange="'+esc(call('consumeChange'))+'" name="cardSale"');return base+(bom?contentModule('预计用料 · BOM V'+bom.version,table(['物料 / 仪器','单次用量','本次使用物料'],bom.lines.map((l,i)=>[text(names(l.type==='sku'?'skus':'equipment',l.item)),text(l.quantity+' '+l.unit+'（'+l.min+'–'+l.max+'）'),l.type==='sku'?select([l.item,...l.alternatives].map(id=>[id,names('skus',id)]),r.alternatives[i]||l.item,`name="alternative-${i}" aria-label="用料${i+1}替代选择"`):text(names('equipment',l.item))]))):body('选择服务规格后查看已生效 BOM。'))+'<p class="muted">优先使用同一客户寄存及可用开瓶余量，未开封库存按效期分配；确认时登记具体瓶号和实际用量。</p>'},r=>{validate(defs,r);if(redeem)r.customer=S.get('cardSales',r.cardSale)?.customer;S.reserve(r);saved('已预占库存，请在消耗单确认治疗完成')},m,860,'预占库存');top().read=(el,r)=>{r.alternatives={};el.querySelectorAll('select[name^="alternative-"]').forEach(s=>r.alternatives[s.name.slice(12)]=s.value)}}
  function consumeChange(){collect();const m=top().model;if(m.cardSale){const c=S.get('cardSales',m.cardSale);m.customer=c.customer;if(!c.remaining.some(x=>x.spec===m.spec&&x.times>0))m.spec=c.remaining.find(x=>x.times>0)?.spec||''}redraw()}
  function consumeActionUI(id,action){if(action!=='confirm')return confirm('取消预占','释放本单预占数量，卡内剩余权益保持不变。',()=>S.consumeAction(id,'cancel'));const c=S.get('consumptions',id),entries=[];for(const p of S.planRows(c)){if(p.type==='equipment'){entries.push({line:p.line,quantity:p.standard});continue}const k=S.get('skus',p.sku);for(const a of c.allocations.filter(a=>a.sku===p.sku)){const b=S.get('batches',a.batch),cap=k.trackOpened&&!b.openedAt?S.unitFactor(k.id,k.containerUnit):a.quantity;let q=a.plannedQuantity??a.quantity;while(q>0){const n=Math.min(q,cap);entries.push({line:p.line,batch:a.batch,quantity:round(n/S.unitFactor(k.id,k.consumptionUnit||k.unit)),unit:k.consumptionUnit||k.unit,mode:k.remainderModes.includes('保留治疗头')?'保留治疗头':k.remainderModes.includes('合规销毁')?'合规销毁':k.remainderModes[0]||'',shiftEnd:'',containerCode:''});q=round(q-n)}}}const m={id,customerId:c.customerId||'',reason:'',entries};open('按瓶 / 批次确认实际消耗',r=>consumptionForm(c,r),r=>{must(r.customerId.trim(),'请填写客户 ID');const result=S.submitConsumption(id,r);saved(result.status==='待偏差审批'?'已提交偏差审批，库存继续预占':'实际消耗已确认，余量去向已记录')},m,1120,'提交实际消耗');top().read=readActual}
  function outbound(kind){const defs=[S.ref('sku','出库商品','skus'),S.ref('store','出库门店','stores'),S.ref('unit','业务单位','unitNames'),S.req('quantity','业务数量','number'),...(kind==='销售出库'?[S.req('price','销售单价（元）','number'),S.req('customer','客户 / 会员号')]:[S.f('customer','领用人 / 接收人'),S.req('reason','出库用途','textarea')]),...(kind==='样品'?[S.f('kind','领用类型','select',['样品','培训','福利'])]:[]),S.ref('doctor','操作医生','doctors',false),S.f('caseNo','病例号'),S.f('consent','知情同意书编号'),S.ref('operator','登记人员','staff',false),S.ref('reviewer','复核人员','staff',false)],m={sku:'',store:'',unit:'',quantity:'',price:0,customer:'',reason:'',kind,doctor:'',caseNo:'',consent:'',operator:'',reviewer:''};open(kind,r=>editForm('outbound',defs,r),r=>{validate(defs,r);must(r.price>=0,'销售价不能为负');S.stockOut(r);saved('已生成出库单及库存流水')},m,860,'确认出库')}
  function saleReturn(){const defs=[S.ref('source','原销售出库单','salesOut'),S.req('quantity','退货数量','number'),S.req('reason','退货原因','textarea')],m={source:'',quantity:'',reason:''};open('销售退货',form(defs,m)+'<p class="muted">按原出库批次退回质量待确认库；质量确认后才可再次出库。</p>',r=>{validate(defs,r);positive(r.quantity);S.transaction('销售退货入待确认库',d=>{const original=S.get('retail',r.source,d);must(original?.kind==='销售出库','原单不是销售出库单');const returned=d.retail.filter(x=>x.source===r.source&&x.kind==='销售退货').reduce((n,x)=>n+x.quantity,0);must(returned+r.quantity<=original.quantity,'退货数量超过原单可退数量');let skip=returned,left=r.quantity,allocations=[];for(const a of original.allocations){let rest=a.quantity;if(skip){const n=Math.min(skip,rest);skip-=n;rest-=n}const q=Math.min(left,rest);if(q>0){const source=S.get('batches',a.batch,d),b={...copy(source),id:uid('LOT'),reserved:0,quantity:0,quality:'待确认',source:r.source};d.batches.push(b);S.movement(d,b,q,'销售退货',r.source);allocations.push({batch:b.id,sku:b.sku,quantity:q,cost:b.cost});left=round(left-q)}if(!left)break}const doc={...r,id:uid('RET'),kind:'销售退货',sku:original.sku,store:original.store,customer:original.customer,amount:round(r.quantity*original.price),cost:round(allocations.reduce((n,x)=>n+x.quantity*x.cost,0)),allocations,time:S.stamp(),status:'待质量确认'};d.retail.unshift(doc);return doc});saved()},m,560,'确认退货')}
  function adjustment(){const defs=[S.ref('source','原消耗单','completedUses'),S.ref('sku','补扣物料','skus'),S.req('quantity','实际用量差异','number'),S.req('reason','偏差原因','textarea')],m={source:'',sku:'',quantity:'',reason:''};open('消耗用量调整',form(defs,m)+'<p class="muted">正数登记漏记的补扣量。已确认用量的减少须走实物盘点与专项复核；开瓶余量在确认消耗时登记。</p>',r=>{validate(defs,r);must(Number.isFinite(r.quantity)&&r.quantity!==0,'请输入非零用量差异');if(r.quantity<0)must(false,'已确认消耗不再回造开瓶余量，请在盘点中登记实物差异并专项复核');S.checkQuantity(r.sku,Math.abs(r.quantity));must(S.get('consumptions',r.source)?.allocations.some(a=>a.sku===r.sku),'物料不属于原消耗单');S.transaction('申请消耗调整',d=>{d.adjustments||=[];const doc={...r,id:uid('ADJ'),time:S.stamp(),status:'待审批'};d.adjustments.unshift(doc);return doc});saved()},m,560,'提交审核')}
  function openBottle(){const defs=[S.ref('batch','未开封库存批次','batches'),S.req('source','使用 / 开封记录'),S.f('containerCode','单瓶追溯码'),S.f('mode','余量归属','select',['客户寄存','继续本班次使用'],true),S.f('customerId','客户 ID'),S.f('customer','客户姓名'),S.f('shiftEnd','本班次结束','datetime-local')],m={batch:'',source:'',containerCode:'',mode:'客户寄存',customerId:'',customer:'',shiftEnd:''};open('登记一支 / 一瓶开封',form(defs,m)+'<p class="muted">按 SKU 容器容量从整包装转入一支开瓶记录，余量归属和开封时限必须符合已配置的产品依据。</p>',r=>{validate(defs,r);S.transaction('按瓶开封登记',d=>{const b=S.openContainer(d,S.get('batches',r.batch,d),r.source,r.containerCode);S.setRemainder(d,b,r.mode,r,r.source);return b});saved()},m,860)}
  function qualityResolve(id){const defs=[S.f('result','处置结论','select',['继续隔离','质量合格放行','转报损']),S.req('reason','处置依据','textarea')],m={result:'继续隔离',reason:''};open('质量待确认处置',form(defs,m),r=>{validate(defs,r);if(r.result==='转报损'){close(true);edit('losses','',{batch:id,quantity:S.available(S.get('batches',id)),reason:'超温',subject:'存货损失',note:r.reason});return}S.transaction('质量处置 / '+r.result,d=>{const b=S.get('batches',id,d);must(b.quality!=='召回锁定','召回批次不能在普通质量处置中放行');if(r.result==='质量合格放行'){must(S.daysLeft(b)>0&&(!b.openExpiry||Date.parse(b.openExpiry)>Date.now()),'已到期批次不能放行');b.quality='合格'}b.qualityNote=r.reason;return b});saved()},m,560)}
  function trace(id){const source=S.get('batches',id);if(!source)return;const batches=S.data.batches.filter(b=>b.sku===source.sku&&b.batch===source.batch),ids=batches.map(b=>b.id),uses=[...S.data.consumptions,...S.data.retail].filter(c=>c.allocations?.some(a=>ids.includes(a.batch))&&['已消耗','已出库'].includes(c.status));open('批次 / UDI 全程追溯',kv({'商品':text(names('skus',source.sku)),'生产批号':text(source.batch),'UDI':text(source.udi),'供应商':text(names('suppliers',source.supplier))})+contentModule('库存去向',tableFor('batches',batches,false))+contentModule('客户使用记录',table(['业务单号','客户 / 会员','门店','医生 / 病例号','时间','状态'],uses.map(c=>[text(c.id),text(c.customer),text(names('stores',c.store)),text((names('staff',c.doctor)==='—'?'':names('staff',c.doctor))+' / '+(c.caseNo||'—')),text(c.confirmed||c.time),tag(c.status)])))+contentModule('批次流转',tableFor('movements',S.data.movements.filter(x=>ids.includes(x.batch)),false)),null,null,1120)}
  function coldResolve(id){const t=S.get('temperatures',id),ids=t.batches||S.data.batches.filter(b=>b.warehouse===t.warehouse).map(b=>b.id);open('冷链断链处置',()=>contentModule('受影响批次',tableFor('batches',S.data.batches.filter(b=>ids.includes(b.id))))+'<p class="muted">逐批登记放行依据或完成报损后，确认此次断链处置完成。</p>',()=>{S.transaction('完成冷链断链处置',d=>{must(d.batches.filter(b=>ids.includes(b.id)).every(b=>b.quality==='合格'||b.quantity===0),'仍有待确认库存，请先逐批处置');const x=S.get('temperatures',id,d);x.status='已处置';return x});saved()}, {},1120,'完成处置')}
  function recallComplete(id){confirm('完成产品召回','核对本批次所有门店的剩余库存均已完成处置。',()=>S.transaction('完成产品召回',d=>{const r=S.get('recalls',id,d),b=S.get('batches',r.batch,d);must(r.status==='执行中','召回状态已变化');must(d.batches.filter(x=>x.sku===b.sku&&x.batch===b.batch).every(x=>x.quantity===0),'本批次仍有库存，请先完成退货或报损处置');r.status='已完成';return r}))}
  function partnerReceive(id){const row=S.get('partnerOrders',id),defs=[S.req('amount','本次回款（元）','number'),S.req('voucher','回款凭证号')],m={amount:round(row.amount-row.received),voucher:''};open('登记外协回款',form(defs,m),r=>{validate(defs,r);positive(r.amount,'回款金额');S.transaction('外协回款登记',d=>{const p=S.get('partnerOrders',id,d);must(r.amount<=round(p.amount-p.received),'超过待回款金额');p.received=round(p.received+r.amount);p.status=p.received===p.amount?'已结清':'部分回款';p.receipts||=[];p.receipts.push({...r,time:S.stamp()});return p});saved()},m,560)}
  function ack(id){confirm('知悉预警','记录本次知悉。风险解除前仍保留该预警。',()=>S.transaction('预警知悉',d=>{if(!d.alertActions.some(x=>x.alert===id))d.alertActions.push({id:uid('ACK'),alert:id,time:S.stamp()});return {id}}))}
  function suggest(id){const r=suggestions().find(r=>r.id===id);if(r)edit('transfers','',{batch:r.batch,to:r.to,sendQuantity:r.quantity,sendUnit:S.get('skus',r.sku).unit,reason:r.reason})}
  function lossFor(id){edit('losses','',{batch:id,quantity:S.available(S.get('batches',id)),reason:S.get('batches',id).openedAt?'开瓶余量过期':S.daysLeft(S.get('batches',id))<0?'过期':'超温',subject:'存货损失'})}
  function showStore(id){views['sc-inventory']='batch';states['sc-inventory:batch']={q:'',status:'',store:id,from:'',to:'',page:1,size:20,selected:[]};go('sc-inventory')}
  function customReport(id){const r=S.get('reportPlans',id);open(r.name,tableFor('report',reports('',r),false),null,null,1120)}
  function download(name,headers,rows){const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,"'$&").replaceAll('"','""')+'"',blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  function exportRows(){const v=view(),cols=S.columns[v.entity]||[];download(v.title+'-'+S.today(),cols.map(c=>c.split(':')[1]),filtered().map(r=>cols.map(c=>raw(r,c.split(':')[0],v.entity))));toast('已导出当前筛选结果')}
  function parseCSV(input){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<input.length;i++){const c=input[i];if(c==='"'){if(quoted&&input[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&input[i+1]==='\n')i++;row.push(value);if(row.some(x=>x.trim()))rows.push(row);row=[];value=''}else value+=c}must(!quoted,'CSV 引号不完整');row.push(value);if(row.some(x=>x.trim()))rows.push(row);return rows.map(row=>row.map(x=>x.trim()))}
  function importBoms(){const m={csv:''},content=()=>body('按模板填写服务规格 ID、配方名称、生效日期、类型（sku / equipment）、物料或仪器 ID、用量、单位、下限、上限、替代料 ID（用 | 分隔）。同一规格合并成一个版本。')+button('下载 CSV 模板','importTemplate')+` <label class="btn"><input type="file" accept=".csv,text/csv" aria-label="选择 BOM CSV 文件" onchange="${esc(call('readImport'))}"></label>`+form([S.req('csv','CSV 内容','textarea')],m);open('BOM 批量导入',content, r=>{const all=parseCSV(r.csv.replace(/^\uFEFF/,'')),expected=['规格ID','配方名称','生效日期','类型','物料ID','用量','单位','下限','上限','替代料ID'];must(all.length>1,'请导入表头及至少一行配方');must(expected.every((h,i)=>all[0][i]===h),'CSV 表头与模板不一致');const groups=new Map();all.slice(1).forEach((row,i)=>{const [spec,name,effective,type,item,qty,unit,min,max,alternatives='']=row;must(row.length===10,'第 '+(i+2)+' 行列数不正确');must(S.get('specs',spec),'第 '+(i+2)+' 行规格不存在');must(/^\d{4}-\d{2}-\d{2}$/.test(effective)&&!Number.isNaN(Date.parse(effective)),'第 '+(i+2)+' 行生效日期无效');must(['sku','equipment'].includes(type),'第 '+(i+2)+' 行类型无效');must(name,'配方名称不能为空');if(!groups.has(spec))groups.set(spec,{name,spec,effective,lines:[]});const b=groups.get(spec);must(b.effective===effective&&b.name===name,'同一规格的名称和生效日必须一致');b.lines.push({type,item,quantity:Number(qty),unit,min:Number(min),max:Number(max),alternatives:alternatives?alternatives.split('|'):[]})});groups.forEach(b=>validateLines(b));S.transaction('批量导入 BOM 版本',d=>{for(const b of groups.values()){must(!d.boms.some(x=>x.spec===b.spec&&x.effective===b.effective&&x.status==='已发布'),'规格 '+b.spec+' 在该生效日期已有发布版本');S.normalizeBom(b,d);b.id=uid('BOM');b.status='已发布';b.version=Math.max(0,...d.boms.filter(x=>x.spec===b.spec).map(x=>x.version))+1;d.boms.unshift(b)}return {id:[...groups.values()].map(x=>x.id).join('、')}});saved('已导入 '+groups.size+' 个 BOM 版本')},m,860,'校验并导入')}
  function importTemplate(){download('BOM导入模板',['规格ID','配方名称','生效日期','类型','物料ID','用量','单位','下限','上限','替代料ID'],[['SP01','海薇注射配方',S.day(1),'sku','SKU01',1,'ml',0.8,1,'SKU02']])}
  async function readImport(){const file=root()?.querySelector('input[type=file]')?.files[0];if(!file)return;const item=top();if(file.size>1024*1024)return error('CSV 文件不能超过 1MB');try{const csv=await file.text();if(top()!==item)return;collect();item.model.csv=csv;redraw()}catch{error('文件读取失败')}}
  function stockDisplay(q,unit,factor,base){if(q==null)return '—';return Math.floor((q+1e-8)/factor)+' '+unit+' + '+round(q-Math.floor((q+1e-8)/factor)*factor)+' '+base+'（'+q+' '+base+'）'}
  function expiryText(value){if(!value)return '—';const n=Date.parse(value)-Date.now();return new Date(value).toLocaleString('zh-CN',{hour12:false})+' / '+(n<=0?'已失效':Math.floor(n/3600000)+'小时 '+Math.ceil(n%3600000/60000)+'分')}
  function unitCell(r,key,type){const k=S.get('skus',r.sku||r.id);if(type==='skus'){if(key==='unitRoles')return [r.purchaseUnit,r.stockUnit,r.salesUnit,r.consumptionUnit].join(' / ');if(key==='precision')return r.splitAllowed?'最小 '+r.step+' '+r.unit+(r.trackOpened?' / 按'+r.containerUnit+'管理':''):'整数 '+r.unit}if(key==='baseConversion'&&type==='units'){try{return '1 '+r.name+' = '+S.unitFactor(r.sku,r.name)+' '+k.unit}catch(e){return e.message}}if(key==='baseQuantity'){if(type==='purchases')return (r.conversion?.baseQuantity??S.convertUnits(r.sku,r.quantity,r.unit))+' '+k.unit;if(type==='transfers')return r.quantity+' '+(k?.unit||S.get('skus',S.get('batches',r.batch)?.sku)?.unit||'')}if(type==='batches'){if(['packages','whole','remainder'].includes(key))return S.stockParts(r)[key];if(key==='openExpiryText')return expiryText(r.openExpiry);if(key==='locationKind')return r.locationKind||'门店库存'}if(type==='transfers'){if(key==='sendDisplay')return (r.sendQuantity??r.quantity)+' '+(r.sendUnit||k?.unit||'基本单位');if(key==='receiveDisplay')return r.receiveQuantity!=null?r.receiveQuantity+' '+r.receiveUnit:'待收货'}if(type==='counts'){const b=S.get('batches',r.batch),sku=S.get('skus',b?.sku),u=r.stockUnit||sku?.stockUnit||sku?.unit,f=r.stockFactor||(sku?S.unitFactor(sku.id,u):1);if(key==='bookDisplay')return stockDisplay(r.book,u,f,r.unit||sku?.unit);if(key==='actualDisplay')return stockDisplay(r.actual,u,f,r.unit||sku?.unit);if(key==='differenceDisplay')return r.difference==null?'—':r.difference+' '+(r.unit||sku?.unit)}if(type==='custodies'){const b=S.get('batches',r.batch);if(key==='quantity')return b?.quantity||0;if(key==='unit')return k?.unit;if(key==='containerCode')return b?.containerCode;if(key==='expiresText')return expiryText(b?.openExpiry)}if(type==='retail'&&key==='businessDisplay')return (r.businessQuantity??r.quantity)+' '+(r.businessUnit||k?.unit||'');}
  function editForm(type,defs,m){let html=form(defs,m);for(const key of ['sku','unit','batch','sendUnit'])html=html.replace('name="'+key+'"','onchange="'+esc(call('editChange',type,key))+'" name="'+key+'"');if(type==='skus'&&m.id)html=html.replace('name="unit"','disabled name="unit"');if(type==='skus')html+='<p class="muted">基本单位创建后不可修改。先创建 SKU，再维护单位换算链。不同包装、促销装和试用装使用独立编码。留存余量须填写产品依据，未配置时仅允许销毁。</p>';if(type==='units')html+='<p class="muted">1 个源单位 = 换算系数 × 目标单位，目标单位须能追溯到基本单位。默认勾选项作为采购默认单位。</p>';if(type==='purchases'||type==='transfers'||type==='outbound'){try{const b=S.get('batches',m.batch),id=type==='transfers'?b?.sku:m.sku,k=S.get('skus',id),q=type==='transfers'?m.sendQuantity:m.quantity,u=type==='transfers'?m.sendUnit:m.unit;if(k&&q&&u)html+=kv({'基本单位数量':text(S.convertUnits(id,q,u)+' '+k.unit),'换算关系':text('1 '+u+' = '+S.unitFactor(id,u)+' '+k.unit)})}catch(e){html+='<p class="muted">'+text(e.message)+'</p>'}}return html}
  function editChange(type,key){collect();const m=top().model;if(type==='skus'&&key==='unit'&&!m.id){for(const f of ['purchaseUnit','stockUnit','salesUnit','consumptionUnit'])m[f]||=m.unit;m.step=['ml','g'].includes(m.unit)?.1:1;m.splitAllowed=['ml','g'].includes(m.unit)}if(['purchases','outbound'].includes(type)&&key==='sku'){const k=S.get('skus',m.sku);m.unit=(type==='purchases'?k?.purchaseUnit:k?.salesUnit)||k?.unit||'';if(type==='purchases')try{m.price=round((k?.cost||0)*S.unitFactor(k.id,m.unit))}catch{m.price=0}}if(type==='transfers'&&key==='batch'){const b=S.get('batches',m.batch),k=S.get('skus',b?.sku);m.sendUnit=k?.stockUnit||k?.unit||''}redraw()}
  function unitCalculator(){const m={sku:'SKU05',quantity:2,from:'箱',to:'ml'};open('多级单位换算试算',r=>{const defs=[S.ref('sku','存货','skus'),S.req('quantity','原数量','number'),S.f('from','源单位','select',S.unitsFor(r.sku),true),S.f('to','目标单位','select',S.unitsFor(r.sku),true)];let html=form(defs,r);for(const key of ['sku','quantity','from','to'])html=html.replace('name="'+key+'"','onchange="'+esc(call('calculatorChange',key))+'" name="'+key+'"');try{const base=S.convertUnits(r.sku,r.quantity,r.from),k=S.get('skus',r.sku);html+=kv({'换算结果':text(r.quantity+' '+r.from+' = '+round(base/S.unitFactor(r.sku,r.to))+' '+r.to),'基本单位记账':text(base+' '+k.unit)})}catch(e){html+=body(text(e.message))}return html},null,m,560)}
  function calculatorChange(key){collect();const m=top().model;if(key==='sku'){const k=S.get('skus',m.sku);m.from=k?.purchaseUnit||k?.unit;m.to=k?.unit}redraw()}
  function unitDetails(type,r){let html='';if(type==='consumptions'){if(r.actualTotals?.length)html+=contentModule('实际用量与 BOM',table(['物料 / 仪器','标准量','允许范围','实际量','基本单位'],r.actualTotals.map(p=>[text(names(p.type==='equipment'?'equipment':'skus',p.sku)),p.standard,p.min+'–'+p.max,p.actual,text(p.unit)])));if(r.actualEntries?.length)html+=contentModule('容器与余量去向',table(['瓶 / 支编号','实际消耗','余量去向','当前余量'],r.actualEntries.map(a=>{const b=S.get('batches',a.batch);return [text(b?.containerCode||b?.batch),text(a.quantity+' '+a.unit),text(a.mode),text(b?b.quantity+' '+S.get('skus',b.sku)?.unit:'—')]})));if(r.actualReason||r.actualProposal)html+=kv({'偏差原因':text(r.actualReason||r.actualProposal?.reason),'审核人':text(names('staff',r.actualReview?.reviewer)),'审核意见':text(r.actualReview?.note)});if(r.cancelReason)html+=kv({'取消原因':text(r.cancelReason)})}if(type==='custodies')html+=kv({'处置结果':text(r.disposition)})+contentModule('客户通知记录',table(['时间','经办人','通知结果','处置说明'],(r.notifications||[]).map(n=>[text(n.time),text(names('staff',n.person)),text(n.result),text(n.disposition)])));if(type==='batches'&&r.openedAt)html+=kv({'瓶 / 支编号':text(r.containerCode),'开封时间':text(r.openedAt),'失效时间':text(expiryText(r.openExpiry)),'客户 ID':text(r.customerId),'当前归属':text(r.locationKind),'政策依据快照':text(r.policySnapshot?.basis),'余量去向':text(r.remainderMode)});if(type==='counts'&&r.splitApproval)html+=kv({'拆零专项审核人':text(names('staff',r.splitApproval.reviewer)),'审核意见':text(r.splitApproval.note)});return html}
  function consumptionForm(c,m){let html=kv({'项目':text(c.name),'客户':text(c.customer),'客户 ID':text(m.customerId),'BOM 版本':text('V'+c.bom.version)})+(!c.customerId?form([S.req('customerId','客户 ID')],m):'');const plans=S.planRows(c);for(const [i,e]of m.entries.entries()){const p=plans.find(p=>p.line===e.line),k=S.get(p.type==='equipment'?'equipment':'skus',p.sku),fields=[S.req('quantity','实际用量','number')];if(p.type==='sku')fields.unshift(S.f('unit','消耗单位','select',S.unitsFor(k.id),true));else fields[0].label='实耗('+p.unit+')';if(p.type==='sku'){const batches=S.bottleOptions(k.id,c.store,m.customerId),batch=S.get('batches',e.batch),allowed=batch?.policySnapshot?.modes||k.remainderModes;fields.unshift(S.f('batch',k.trackOpened?'瓶号 / 批次':'使用批次','select',batches.map(b=>[b.id,(b.containerCode||'未开封整支')+' / '+b.batch+' / '+b.quantity+' '+k.unit+(b.customerId?' / 本客户寄存':'')]),true));if(k.trackOpened)fields.push(S.f('containerCode','新瓶追溯码'),S.f('mode','余量去向','select',allowed,true),...(e.mode==='继续本班次使用'?[S.req('shiftEnd','本班次截止','datetime-local')]:[]))}let body=form(fields.map(f=>({...f,key:'actual-'+i+'-'+f.key})),Object.fromEntries(Object.entries(e).map(([key,v])=>['actual-'+i+'-'+key,v])),'sc-actual');body=body.replace('name="actual-'+i+'-unit"','onchange="'+esc(call('actualChange',i,'unit',e.unit||p.unit))+'" name="actual-'+i+'-unit"');for(const key of ['batch','mode'])body=body.replace('name="actual-'+i+'-'+key+'"','onchange="'+esc(call('actualChange',i,key))+'" name="actual-'+i+'-'+key+'"');html+=contentModule(k.name+' · 标准 '+p.standard+' '+p.unit+' / 允许 '+p.min+'–'+p.max+' '+p.unit,body,p.type==='sku'?link('再用一瓶 / 批次','addActual',p.line)+link('移除此行','removeActual',i):'')}return html+form([S.f('reason','偏差原因','textarea')],m)+'<p class="muted">新开瓶按完整容器转出；实际用量扣减后，剩余量按所选去向处理。超出 BOM 区间须审批后才执行。</p>'}
  function readActual(el,m){for(const [i,e]of m.entries.entries())for(const key of ['batch','quantity','unit','mode','shiftEnd','containerCode']){const c=el.querySelector('[name="actual-'+i+'-'+key+'"]');if(c)e[key]=c.type==='number'?(c.value===''?'':Number(c.value)):c.value}}
  function actualChange(i,key,previous){collect();if(key==='unit'){const m=top().model,e=m.entries[i],p=S.planRows(S.get('consumptions',m.id)).find(p=>p.line===e.line);if(e.quantity!=='')e.quantity=round(e.quantity*S.unitFactor(p.sku,previous)/S.unitFactor(p.sku,e.unit))}if(key==='batch'){const e=top().model.entries[i],b=S.get('batches',e.batch),k=S.get('skus',b?.sku),modes=b?.policySnapshot?.modes||k?.remainderModes||[];if(!modes.includes(e.mode))e.mode=modes[0]||''}redraw()}
  function addActual(line){collect();const m=top().model,c=S.get('consumptions',m.id),p=S.planRows(c).find(p=>p.line===line),k=S.get('skus',p.sku);m.entries.push({line,batch:'',quantity:'',unit:k.consumptionUnit||k.unit,mode:k.remainderModes[0]||'',shiftEnd:'',containerCode:''});redraw()}
  function removeActual(i){collect();const m=top().model,e=m.entries[i];must(m.entries.filter(x=>x.line===e.line).length>1,'每项物料至少保留一行');m.entries.splice(i,1);redraw()}
  function consumeReview(id){const c=S.get('consumptions',id),defs=[S.ref('reviewer','审核人','staff'),S.req('note','审核意见','textarea')],m={reviewer:'',note:''};open('实际用量偏差审核',contentModule('超范围明细',table(['物料 / 仪器','标准用量','允许范围','申请实际量','单位'],c.deviations.map(p=>[text(names(p.type==='equipment'?'equipment':'skus',p.sku)),p.standard,p.min+'–'+p.max,p.actual,p.unit])))+kv({'偏差原因':text(c.actualProposal?.reason)})+form(defs,m),r=>{validate(defs,r);S.approveConsumption(id,r);saved('偏差已审核，按实际用量完成扣减')},m,860,'审核并确认消耗')}
  function countReview(id){const c=S.get('counts',id),defs=[S.ref('reviewer','专项复核人','staff'),S.req('note','复核意见','textarea')],m={reviewer:'',note:''};open('拆零盘点差异专项复核',kv({'账面':text(unitCell(c,'bookDisplay','counts')),'实盘':text(unitCell(c,'actualDisplay','counts')),'差异':text(unitCell(c,'differenceDisplay','counts')),'差异说明':text(c.note)})+form(defs,m),r=>{validate(defs,r);S.approveCount(id,r);saved()},m,560,'审核调整库存')}
  function custodyNotice(id){const defs=[S.ref('person','经办人','staff'),S.req('result','客户通知结果','textarea'),S.f('disposition','处置结果说明','textarea')],m={person:'',result:'',disposition:''};open('寄存通知与处置记录',form(defs,m),r=>{validate(defs,r);S.notifyCustody(id,r);saved('已记录通知结果')},m,560)}
  async function retryStorage(){try{await S.retryPersist();render();toast('已保存')}catch(e){error(e.message)}}
  function leave(){clearInterval(expiryTimer);expiryTimer=null;if(listening){document.removeEventListener('keydown',onKey,true);listening=false}while(stack.length){stack.pop();syncDrawerLayer(document.querySelector('#mergeDrawers'),'sc-'+stack.length,'')}syncDrawerInteraction()}
  PCUI.registerPager('sc-page',value=>{state().page=value.currentPage;state().size=value.pageSize||state().size;render()});
